const b = $input.first().json.body ?? $input.first().json;

const emoji = b.status === 'won' ? '✅' : b.status === 'lost' ? '❌' : '⚪️';
const dir = (b.direction || '').toUpperCase();
const streakLine = b.status === 'won'
  ? `🔥 streak now *${b.currentStreak}* (best ${b.bestStreak})`
  : b.status === 'lost'
    ? `streak reset to 0 (best ${b.bestStreak})`
    : `streak unaffected (*${b.currentStreak}*)`;

const badgeLine = (b.newBadges && b.newBadges.length)
  ? `\n🏅 New badge${b.newBadges.length > 1 ? 's' : ''}: ${b.newBadges.join(', ')}`
  : '';

const payoutLine = (typeof b.payout === 'number' && b.payout > 0)
  ? `\n💰 payout: *${b.payout.toFixed(2)}* USDso`
  : '';

const text = `${emoji} *${b.displayName}* called *${b.symbol} ${dir}* (${b.window}) — *${(b.status || '').toUpperCase()}*\n${streakLine}${payoutLine}${badgeLine}\n\n[tx](https://shannon-explorer.somnia.network/tx/${b.txHash})`;

return [{ json: { ...b, telegramText: text } }];
